message.content:
{
  "avaliacoes": [
    {
      "criterio": "aderencia_curricular",
      "nota": 2,
      "justificativa": "O plano foca apenas no algoritmo BubbleSort (ordenação) e não aborda outros algoritmos clássicos de manipulação de listas previstos na habilidade (inserção, remoção, busca)."
    },
    {
      "criterio": "alinhamento_objetivos",
      "nota": 2,
      "justificativa": "Os objetivos específicos tratam só de ordenação, enquanto o objetivo geral menciona \"algoritmos clássicos de manipulação sobre listas\", gerando desalinhamento parcial."
    },
    {
      "criterio": "coerencia_metodologica",
      "nota": 3,
      "justificativa": "A metodologia descrita (demonstração no projetor seguida de prática nos computadores) está refletida nas etapas ET1 e ET2, respeitando o tipo de aula prática e apresentando sequência lógica."
    },
    {
      "criterio": "viabilidade",
      "nota": 3,
      "justificativa": "Os recursos (projetor e computadores) coincidem com os listados e os tempos (20 min + 30 min) são realistas para as atividades propostas."
    },
    {
      "criterio": "avaliacao_aprendizagem",
      "nota": 2,
      "justificativa": "As evidências são observáveis, porém os critérios de avaliação são genéricos (\"explicar corretamente\", \"manipular e ordenar corretamente\") e não apresentam rubricas detalhadas para discriminar desempenho adequado de inadequado."
    },
    {
      "criterio": "inclusao",
      "nota": 3,
      "justificativa": "As adaptações ADP1 e ADP2 oferecem estratégias concretas (perguntas adicionais e acompanhamento individual) que mantêm os objetivos e utilizam os mesmos recursos."
    }
  ],
  "falhas": [
    {
      "id": "F1",
      "criterio": "aderencia_curricular",
      "componente": "objetivos",
      "gravidade": "maior",
      "descricao": "Conteúdos e objetivos limitam-se ao BubbleSort, omitindo outros algoritmos clássicos de manipulação de listas previstos na habilidade EF08CO03.",
      "correcao_sugerida": "Ampliar os conteúdos e incluir objetivos específicos que abordem, ao menos de forma breve, algoritmos de inserção, remoção e busca, ou explicitar que a aula trata apenas de ordenação como parte da habilidade."
    },
    {
      "id": "F2",
      "criterio": "alinhamento_objetivos",
      "componente": "objetivos",
      "gravidade": "maior",
      "descricao": "Objetivo geral menciona \"algoritmos clássicos de manipulação sobre listas\", mas os objetivos específicos tratam exclusivamente de ordenação, gerando desalinhamento.",
      "correcao_sugerida": "Reformular o objetivo geral para refletir o foco exclusivo em ordenação ou acrescentar objetivos específicos que cubram outras manipulações de listas."
    },
    {
      "id": "F3",
      "criterio": "avaliacao_aprendizagem",
      "componente": "avaliacao_preliminar",
      "gravidade": "maior",
      "descricao": "Os critérios de avaliação (\"explicar corretamente\", \"manipular e ordenar corretamente\") são vagos e não apresentam rubricas ou indicadores claros para diferenciar desempenho adequado de inadequado.",
      "correcao_sugerida": "Definir rubricas detalhadas com indicadores observáveis (ex.: identificar corretamente a troca de elementos, ordenar lista em até X passos) para cada evidência."
    }
  ],
  "resumo": "O plano atende parcialmente a habilidade ao focar só em BubbleSort, apresenta objetivos alinhados à prática mas não ao escopo total da habilidade, mantém coerência metodológica e viabilidade, porém a avaliação carece de rubricas claras; as adaptações são adequadas."
}

